"""Wishlist persistence, migration, safe editing, matching and companion recommendations. Synthetic data only."""
import asyncio, subprocess, sys, time
from pathlib import Path
from playwright.async_api import async_playwright
ROOT=Path(__file__).resolve().parent.parent
PORT=8828
failures=[]
def check(ok, msg):
    print(('ok   ' if ok else 'FAIL ')+msg)
    if not ok: failures.append(msg)
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        ctx=await b.new_context(viewport={'width':390,'height':844})
        await ctx.route('**/*',lambda r:r.continue_() if r.request.url.startswith(f'http://localhost:{PORT}') else r.abort())
        page=await ctx.new_page();errs=[];page.on('pageerror',lambda e:errs.append(str(e)))
        await page.goto(f'http://localhost:{PORT}/manifest.webmanifest')
        await page.evaluate("""() => new Promise((resolve,reject)=>{const r=indexedDB.open('marginalia',9);r.onupgradeneeded=()=>{for(const s of ['texts','notes','content','covers','terms','drafts','compares','files','trash','trashlist','paths'])r.result.createObjectStore(s)};r.onsuccess=()=>{const d=r.result,t=d.transaction(['texts','paths'],'readwrite');t.objectStore('texts').put({title:'Ethics',author:'Benedict de Spinoza',status:'reading'},'ethics');t.objectStore('paths').put({version:1,n:'Earlier path',d:'',steps:[],createdAt:1,updatedAt:1},'p');t.oncomplete=()=>{d.close();resolve()};t.onerror=()=>reject(t.error)}})""")
        await page.evaluate("localStorage.setItem('mg-classics','1')")
        await page.goto(f'http://localhost:{PORT}/index.html');await page.wait_for_function("S.mode==='ready'")
        check(await page.evaluate("idb.version===DB_VERSION && S.texts.has('ethics') && S.paths.has('p') && S.wishlist.size===0"),'version 9 upgrades without losing books or paths')
        await page.evaluate("go({screen:'library'})")
        await page.click('#openwishlist');await page.click('#newwish')
        await page.fill('#wish-title','A book <em>literal</em>');await page.fill('#wish-author','A scholar')
        await page.fill('#wish-note','For the seminar');await page.select_option('#wish-forBook','ethics')
        await page.fill('#wish-url','javascript:alert(1)');await page.click('#sheetroot button[type=submit]')
        check(await page.locator('#err').inner_text()!='','unsafe link refused before saving')
        await page.fill('#wish-url','https://example.com/book');await page.click('#sheetroot button[type=submit]');await page.wait_for_function('S.wishlist.size===1 && !NAV.overlay')
        check(await page.locator('.discovery-card h2 em').count()==0,'wishlist title is escaped')
        check(await page.evaluate("[...S.wishlist.values()][0].forBook==='ethics'"),'companion link is kept with wishlist book')
        key=await page.evaluate('[...S.wishlist.keys()][0]')
        await page.click('[data-wishedit]');await page.fill('#wish-note','Revised reason');await page.click('#sheetroot button[type=submit]');await page.wait_for_function('!NAV.overlay')
        await page.reload();await page.wait_for_function("S.mode==='ready'")
        check(await page.evaluate("[...S.wishlist.values()][0].note==='Revised reason'"),'wishlist edits survive reload')
        await page.evaluate("go({screen:'recommendations',recBook:'ethics'})")
        check(await page.locator('[data-rec-id="nadler-ethics"]').count()==1,'Spinoza Ethics gets its sourced commentary')
        await page.click('[data-wishrec="nadler-ethics"]');await page.wait_for_function('S.wishlist.size===2')
        check(await page.locator('[data-rec-id="nadler-ethics"] [data-wishedit]').count()==1,'saved recommendation changes to wishlist edit')
        check(await page.evaluate("[...S.wishlist.values()].find(w=>w.author==='Steven Nadler').forBook==='ethics'"),'recommended book remembers its reading context')
        await page.evaluate("go({screen:'wishlist'})")
        await page.click(f'[data-wishdelete="{key}"]');await page.click(f'[data-wishdelete="{key}"]');await page.wait_for_function('S.wishlist.size===1')
        await page.click('#toast .toastbtn');await page.wait_for_function('S.wishlist.size===2')
        check(True,'removing a wishlist book offers a working Undo')
        validations=await page.evaluate("""() => {const w=[...S.wishlist.values()][0];return [validWish(w),validWish({...w,status:'bad'}),validWish({...w,url:'data:text/html,hello'}),validWish({...w,title:''}),validWish({...w,extra:true}),validWish({...w,note:'x'.repeat(10001)})]}""")
        check(validations==[True,False,False,False,False,False],'backup validator rejects malformed wishlist records')
        check(await page.evaluate("!sameBook({title:'Spinoza: Practical Philosophy',author:'Gilles Deleuze'},{title:'Spinoza: Another Work',author:'Gilles Deleuze'})"),'deduplication preserves distinct works with the same title prefix')
        match=await page.evaluate("""() => [companionMatches({title:'Ethics',author:'Aristotle'},READING_COMPANIONS[0].base),companionMatches({title:'Ethics with Spinoza',author:'Spinoza'},READING_COMPANIONS[0].base),companionMatches({title:'Ethics',author:''},READING_COMPANIONS[0].base),companionMatches({title:'Ethics: translated edition',author:'Spinoza, Benedict'},READING_COMPANIONS[0].base)]""")
        check(match==[False,False,False,True],'matching distinguishes author and exact work, tolerating edition subtitles')
        await page.evaluate("""async()=>{const r=READING_COMPANIONS[0];await put('texts','owned',{title:r.title,author:r.author});go({screen:'recommendations'});} """)
        check(await page.locator('[data-rec-id="nadler-ethics"]').count()==0,'general suggestions exclude books already on the shelf')
        await page.evaluate("go({screen:'recommendations',recBook:'ethics'})")
        check(await page.locator('[data-rec-id="nadler-ethics"] [data-open="owned"]').count()==1,'book-specific companions open an existing copy')
        await page.evaluate("put('texts','unknown',{title:'Uncatalogued work',author:'Unknown author'}).then(()=>go({screen:'recommendations',recBook:'unknown'}))")
        check('No sourced pairing' in await page.locator('#main').inner_text(),'unknown books receive an honest empty state')
        await page.click('[data-wishfor]');await page.fill('#wish-title','Another companion');await page.click('#sheetroot button[type=submit]');await page.wait_for_function('!NAV.overlay')
        check(await page.evaluate("[...S.wishlist.values()].some(w=>w.forBook==='unknown')"),'manual companions work for any imported book')
        check('Your companion selections' in await page.locator('#main').inner_text() and 'Another companion' in await page.locator('#main').inner_text(),'manual companion appears on its linked book’s recommendations')
        await page.evaluate("""async()=>{await put('wishlist','dr',{title:'Difference and Repetition',author:'Gilles Deleuze',note:'',url:'',forBook:'',status:'wanted',createdAt:1,updatedAt:1});go({screen:'recommendations'});} """)
        check(await page.locator('[data-rec-id="somers-hall-difference"]').count()==1,'wishlisted primary texts inform recommendations')
        await page.evaluate("go({screen:'wishlist'})");await page.click('[data-wishedit="dr"]');await page.select_option('#wish-status','obtained');await page.click('#sheetroot button[type=submit]');await page.wait_for_function('!NAV.overlay')
        check(await page.evaluate("S.wishlist.get('dr').status==='obtained'"),'obtained status is saved')
        for w in [320,390,1280]:
            await page.set_viewport_size({'width':w,'height':844})
            for screen in ['wishlist','recommendations']:
                await page.evaluate("s=>{go({screen:s});S.recAll=true;render()}",screen)
                check(await page.evaluate('document.documentElement.scrollWidth<=innerWidth'),f'{screen} fits {w}px')
        check(not errs,f'no script errors: {errs}')
        await ctx.close();await b.close()
srv=subprocess.Popen([sys.executable,'-m','http.server',str(PORT),'-d',str(ROOT)],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
try: time.sleep(1);asyncio.run(main())
finally:srv.terminate()
print(f'{len(failures)} failed' if failures else 'all passed')
sys.exit(bool(failures))
